    def _load_buggy_files(path_to_buggy):
        """Loads all files in path_to_buggy. Returns a dictionary where keys are file names and values are
        dictionaries containing the lines in the file.

        :param path_to_buggy: the path to the folder containing the buggy files
        :return: a dictionary of dictionaries
        """
        result = dict()
        for root, dirs, files in os.walk(path_to_buggy):
            for filename in files:
                with open(os.path.join(root, filename)) as f:
                    file_content = dict()
                    for i, line in enumerate(f):
                        file_content[i] = line
                    result[filename] = file_content
        return result

    @staticmethod
    def _save_fixed_files(path_to_fixed, result):
        """Saves all fixed files in path_to_fixed.

        :param path_to_fixed: the path to the folder containing the fixed files
        :param result: the result dictionary from load_buggy_files
        """
        for file_name, file_content in result.items():
            with open(os.path.join(path_to_fixed, file_name), 'w') as f:
                for i in range(len(file_content)):
                    f.write(file_content[i])
